<template>
 <div class="compatibility-page"><PageHead title="兼容性管理" desc="选择商品，勾选适用型号，保存即可。"><el-button v-if="returnTo" @click="router.push(returnTo)">返回选购 / 来源</el-button><el-button v-if="canMaintain" type="primary" data-new-association @click="openEditor(selectedIds)">新增适用关系</el-button></PageHead>
 <el-alert v-if="error" :title="error" type="warning" :closable="false" data-association-error/>
 <section class="panel"><div class="list-tools"><el-select v-model="typeId" clearable filterable placeholder="全部配件产品类型" aria-label="适用关系产品类型"><el-option v-for="t in accessoryTypes" :key="t.id" :value="t.id" :label="t.name"/></el-select><el-input v-model="keyword" clearable placeholder="搜索商品、规格、SKU或适用型号" aria-label="搜索适用关系"/><el-button v-if="selectedIds.length&&canMaintain" @click="openEditor(selectedIds)">批量编辑（{{selectedIds.length}}）</el-button><el-button v-if="selectedIds.length" text @click="selectedIds=[]">取消选择</el-button></div>
 <el-table :data="pageRows" row-key="id" data-association-list><el-table-column v-if="canMaintain" width="48"><template #header><el-checkbox :model-value="pageRows.length>0&&pageRows.every(s=>selectedIds.includes(s.id))" :indeterminate="pageRows.some(s=>selectedIds.includes(s.id))&&!pageRows.every(s=>selectedIds.includes(s.id))" aria-label="选择当前页商品" @change="selectPage(Boolean($event))"/></template><template #default="{row}"><el-checkbox :model-value="selectedIds.includes(row.id)" :data-association-select="row.id" :aria-label="'选择 '+row.name" @change="selectMain(row.id,Boolean($event))"/></template></el-table-column><el-table-column label="配件商品" min-width="280"><template #default="{row}"><strong>{{row.name}}</strong><small>{{row.spec||'标准规格'}} · {{row.code}}</small></template></el-table-column><el-table-column prop="typeName" label="产品类型" width="130"/><el-table-column label="适用设备型号" min-width="300"><template #default="{row}"><div class="model-tags"><el-tag v-for="m in row.models.slice(0,3)" :key="m.key" size="small" effect="plain">{{m.label}}</el-tag><el-tooltip v-if="row.models.length>3" :content="modelNames(row.models)"><span>共 {{row.models.length}} 个型号</span></el-tooltip><span v-if="!row.models.length" class="muted">暂未选择型号</span></div></template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button text type="primary" :data-edit-association="row.id" @click="openEditor([row.id],true)">{{canMaintain?'编辑':'查看'}}</el-button><el-button v-if="canDelete&&row.models.length" text type="danger" :data-unlink-association="row.id" @click="unlink(row.id)">取消关联</el-button></template></el-table-column></el-table>
 <el-pagination v-model:current-page="page" :page-size="20" :total="rows.length" layout="total, prev, pager, next"/><p class="muted footer-note">本页维护商品与型号的直接关联；其他已保存资料及历史清单保持。</p></section>
 <el-dialog v-model="opened" title="选择商品和适用型号" width="min(1080px,96vw)" :close-on-click-modal="false" :before-close="close">
 <div class="editor-grid"><section><h2>选择需要配置的商品</h2><div class="filters"><el-select v-model="editorType" clearable filterable placeholder="全部配件产品类型" aria-label="编辑产品类型"><el-option v-for="t in accessoryTypes" :key="t.id" :value="t.id" :label="t.name"/></el-select><el-input v-model="productSearch" clearable placeholder="搜索商品或规格" aria-label="搜索关联商品"/></div><div class="pick-list"><div v-for="s in editorProducts" :key="s.id" class="pick-row"><el-checkbox :model-value="skuIds.includes(s.id)" :disabled="busy||!canMaintain" :data-edit-product="s.id" :aria-label="'关联商品 '+s.name" @change="selectProduct(s.id,Boolean($event))"><strong>{{s.name}}</strong><small>{{s.spec||s.code}}</small></el-checkbox></div><p v-if="!editorProducts.length" class="muted">没有匹配的销售商品，请调整产品类型或搜索。</p></div><p class="muted">已选 {{skuIds.length}} 个具体SKU，筛选不会取消已选项。</p></section>
 <section><h2>适用哪些设备型号？</h2><el-input v-model="modelSearch" clearable placeholder="搜索设备型号" aria-label="搜索适用型号"/><div class="pick-tools"><el-button text :disabled="busy||!canMaintain" @click="selectModels(true)">选择当前结果</el-button><el-button text :disabled="busy||!canMaintain" @click="selectModels(false)">取消当前结果</el-button></div><div class="pick-list"><div v-for="m in filteredModels" :key="m.key" class="pick-row"><el-checkbox :model-value="modelKeys.includes(m.key)" :disabled="busy||!canMaintain" :data-associate-model="m.key" @change="toggleModel(m.key,Boolean($event))">{{m.label}}</el-checkbox></div><p v-if="!filteredModels.length" class="muted">没有找到明确型号，请先完善现有商品模型的型号资料。</p></div><p class="muted">请根据实际产品资料勾选，系统不会按品牌或名称推断适用。</p></section></div>
 <div v-if="canMaintain" class="mode-row"><el-radio-group :model-value="mode" :disabled="busy" aria-label="适用型号保存方式" @change="setMode(String($event))"><el-radio-button value="add">新增适用型号</el-radio-button><el-radio-button value="replace">替换适用型号</el-radio-button></el-radio-group><p>{{mode==='add'?'为选中商品增加型号，保留各商品原有的其他关联。':'用当前勾选型号替换选中商品的普通型号关联；取消的型号回到未关联。'}}</p></div>
 <div class="selection-preview" data-association-preview>已选 <strong>{{skuIds.length}}</strong> 个 SKU，<strong>{{modelKeys.length}}</strong> 个适用型号。保存只影响明确选中的商品。</div><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" data-association-save-error/><p v-if="problem&&dirty" class="form-error">{{problem}}</p>
 <template #footer><el-button :disabled="busy" @click="close(()=>opened=false)">{{canMaintain?'取消':'关闭'}}</el-button><el-button v-if="canMaintain" type="primary" :loading="busy" :disabled="busy||!!problem" data-save-associations @click="save">保存关联</el-button></template>
 </el-dialog></div>
</template>
<script setup lang="ts">
import {roleOfType} from '../domain/compatibility'

import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ElMessageBox,ElMessage} from 'element-plus'
import PageHead from '../components/PageHead.vue'
import {useCatalogStore} from '../stores/catalog'
import {isRealSku} from '../domain/catalogIdentity'
import {familyProductTypeId} from '../domain/productIdentity'
import {listDeviceModels,deviceHostKey} from '../domain/deviceResolution'
import {simpleClaims,associationChanges,workspaceBasis} from '../domain/compatibilityWorkspace'
import {declarationDefaults} from '../domain/accessoryCompatibilityQuery'
import {internalReturnLocation} from '../domain/internalNavigation'
const store=useCatalogStore(),route=useRoute(),router=useRouter(),typeId=ref(''),keyword=ref(''),page=ref(1),selectedIds=ref<string[]>([]),opened=ref(false),skuIds=ref<string[]>([]),modelKeys=ref<string[]>([]),mode=ref<'add'|'replace'>('add'),modeExplicit=ref(false),editorType=ref(''),productSearch=ref(''),modelSearch=ref(''),busy=ref(false),error=ref(''),saveError=ref(''),initial=ref(''),baselines=ref<Record<string,string>>({})
let alive=true
const actor=()=>JSON.stringify([store.activeUserId,store.previewUserId]),returnTo=computed(()=>internalReturnLocation(route.query.returnTo)),canMaintain=computed(()=>['create','update','delete'].some(a=>store.can('product:compatibility:'+a))),canDelete=computed(()=>store.can('product:compatibility:delete')),accessoryTypes=computed(()=>store.data.productTypes.filter(t=>roleOfType(store.data,t.id)==='accessory')),models=computed(()=>listDeviceModels(store.data)),modelByKey=computed(()=>new Map(models.value.map(m=>[m.key,m])))
const modelNames=(items:{label:string}[])=>items.map(m=>m.label).join('、')
function currentModels(id:string){return [...new Set(simpleClaims(store.data,[id]).filter(c=>{const d=declarationDefaults(c);return d.conclusion==='compatible'&&d.verification==='confirmed'}).map(c=>deviceHostKey(c.host)))].flatMap(key=>{const m=modelByKey.value.get(key);return m?[m]:[]})}
const products=computed(()=>store.data.skus.filter(s=>isRealSku(store.data,s)).flatMap(s=>{const f=store.data.families.find(f=>f.id===s.familyId),type=store.data.productTypes.find(t=>t.id===familyProductTypeId(store.data,s.familyId));return f&&type&&roleOfType(store.data,type.id)==='accessory'?[{id:s.id,name:s.skuName||f.name,code:s.code,spec:Object.values(s.variantAttrs).join(' · '),typeId:type.id,typeName:type.name,models:currentModels(s.id)}]:[]}))
const rows=computed(()=>{const q=keyword.value.trim().toLowerCase();return products.value.filter(s=>(!typeId.value||s.typeId===typeId.value)&&(!q||(s.name+' '+s.spec+' '+s.code+' '+s.models.map(m=>m.label).join(' ')).toLowerCase().includes(q)))}),pageRows=computed(()=>rows.value.slice((page.value-1)*20,page.value*20)),editorProducts=computed(()=>{const q=productSearch.value.trim().toLowerCase();return products.value.filter(s=>(!editorType.value||s.typeId===editorType.value)&&(!q||(s.name+' '+s.spec+' '+s.code).toLowerCase().includes(q)))}),filteredModels=computed(()=>models.value.filter(m=>m.label.toLowerCase().includes(modelSearch.value.trim().toLowerCase())))
const stamp=()=>JSON.stringify([skuIds.value,modelKeys.value,mode.value]),dirty=computed(()=>opened.value&&stamp()!==initial.value),changes=computed(()=>associationChanges(store.data,skuIds.value,modelKeys.value,mode.value,'人工确认：'+(store.currentUser?.displayName||'维护人')+'在兼容性管理中明确选择适用型号；未附加资料说明。')),problem=computed(()=>skuIds.value.some(id=>!products.value.some(s=>s.id===id))?'所选商品已变化，请重新选择':skuIds.value.some(id=>baselines.value[id]!==workspaceBasis(store.data,[id]))?'所选商品的资料已更新，请重新打开核对；本次选择仍保留。':changes.value.ok?'':changes.value.message)
watch([typeId,keyword],()=>page.value=1)
function selectMain(id:string,on:boolean){selectedIds.value=on?[...new Set([...selectedIds.value,id])]:selectedIds.value.filter(x=>x!==id)}
function selectPage(on:boolean){selectedIds.value=on?[...new Set([...selectedIds.value,...pageRows.value.map(s=>s.id)])]:selectedIds.value.filter(id=>!pageRows.value.some(s=>s.id===id))}
function openEditor(ids:string[]=[],edit=false){if(busy.value)return;skuIds.value=ids.filter(id=>products.value.some(s=>s.id===id));modelKeys.value=edit&&skuIds.value.length===1?currentModels(skuIds.value[0]!).map(m=>m.key):[];mode.value=edit&&skuIds.value.length===1?'replace':'add';modeExplicit.value=false;editorType.value=typeId.value;productSearch.value='';modelSearch.value='';saveError.value='';baselines.value=Object.fromEntries(skuIds.value.map(id=>[id,workspaceBasis(store.data,[id])]));initial.value=stamp();opened.value=true}
function selectProduct(id:string,on:boolean){if(on){if(!baselines.value[id])baselines.value[id]=workspaceBasis(store.data,[id]);skuIds.value=[...new Set([...skuIds.value,id])]}else skuIds.value=skuIds.value.filter(x=>x!==id);if(skuIds.value.length>1&&!modeExplicit.value)mode.value='add';saveError.value=''}
function toggleModel(key:string,on:boolean){modelKeys.value=on?[...new Set([...modelKeys.value,key])]:modelKeys.value.filter(x=>x!==key);saveError.value=''}
function selectModels(on:boolean){modelKeys.value=on?[...new Set([...modelKeys.value,...filteredModels.value.map(m=>m.key)])]:modelKeys.value.filter(key=>!filteredModels.value.some(m=>m.key===key));saveError.value=''}
function setMode(value:string){mode.value=value==='replace'?'replace':'add';modeExplicit.value=true;saveError.value=''}
async function discard(){if(!dirty.value)return true;try{await ElMessageBox.confirm('有未保存的型号选择，确定放弃？','保留或放弃修改',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑'});opened.value=false;return true}catch{return false}}
async function close(done:()=>void){if(!busy.value&&await discard())done()}
async function save(){if(busy.value||problem.value||!changes.value.ok)return;const commands=changes.value.changes;if(!commands.length){opened.value=false;ElMessage.success('适用型号未变化');return}const owner=actor(),expected=stamp(),basis=workspaceBasis(store.data,skuIds.value),removed=commands.filter(c=>c.kind==='remove').length
 if(removed){try{await ElMessageBox.confirm('将取消所选商品中 '+removed+' 条未勾选的普通型号关联，其他商品及已保存的特殊资料保持。','确认替换适用型号',{confirmButtonText:'确认替换',cancelButtonText:'取消'})}catch{return}}
 if(owner!==actor()||expected!==stamp())return;busy.value=true;saveError.value='';try{const result=await store.saveCompatibilityWorkspace([...skuIds.value],commands,[],basis,()=>alive&&owner===actor()&&expected===stamp());if(owner!==actor()||!alive)return;if(!result.ok){saveError.value=result.message||'保存失败，选择保留';return}initial.value=stamp();opened.value=false;ElMessage.success('适用型号已保存')}catch(e){if(owner===actor())saveError.value=String(e)}finally{busy.value=false}}
async function unlink(id:string){if(busy.value)return;const owner=actor(),basis=workspaceBasis(store.data,[id]),result=associationChanges(store.data,[id],[],'replace','人工取消普通型号关联');if(!result.ok){error.value=result.message;return}const count=result.changes.length;try{await ElMessageBox.confirm('取消此商品的 '+count+' 条普通型号关联？其他商品和历史资料保持。','取消适用关联',{confirmButtonText:'确认取消关联',cancelButtonText:'返回'})}catch{return}if(owner!==actor())return;busy.value=true;try{const saved=await store.saveCompatibilityWorkspace([id],result.changes,[],basis,()=>alive&&owner===actor());if(!saved.ok)error.value=saved.message||'取消失败';else ElMessage.success('普通型号关联已取消')}catch(e){error.value=String(e)}finally{busy.value=false}}
function unload(e:BeforeUnloadEvent){if(busy.value||dirty.value){e.preventDefault();e.returnValue=''}}window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{alive=false;window.removeEventListener('beforeunload',unload)});onBeforeRouteLeave(async()=>!busy.value&&await discard());onBeforeRouteUpdate(async to=>{if(busy.value||!await discard())return false;enter(to.query);return true})
function enter(q:Record<string,unknown>){const ids=String(q.skuIds||q.targetId||'').split(',').filter(id=>products.value.some(s=>s.id===id));if(ids.length)openEditor(ids,ids.length===1)}
watch(actor,()=>{opened.value=false;skuIds.value=[];modelKeys.value=[];selectedIds.value=[];baselines.value={};error.value='';saveError.value=''});onMounted(()=>enter(route.query))
</script>
<style scoped>.compatibility-page{max-width:1700px;margin:auto}.panel{padding:20px}.list-tools,.filters{display:flex;gap:10px;align-items:center;margin-bottom:18px}.list-tools .el-select{width:220px;flex:none}.list-tools .el-input{max-width:400px}.model-tags{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.model-tags span,.muted,small{font-size:12px;color:var(--el-text-color-secondary);line-height:1.6}small{display:block;margin-top:5px}.el-pagination{margin-top:18px}.footer-note{margin:16px 0 0}.editor-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.editor-grid h2{font-size:16px;margin:0 0 14px}.filters .el-select{width:170px;flex:none}.pick-list{height:330px;overflow:auto;border:1px solid var(--el-border-color-light);border-radius:8px;padding:8px}.pick-row{display:block;padding:8px;border-radius:6px}.pick-row:hover{background:var(--el-fill-color-light)}.pick-row .el-checkbox{height:auto;white-space:normal;max-width:100%;align-items:flex-start}.pick-row :deep(.el-checkbox__label){white-space:normal;line-height:1.6;overflow-wrap:anywhere}.pick-tools{height:40px;display:flex;align-items:center}.mode-row{margin:20px 0 0}.mode-row p{font-size:12px;color:var(--el-text-color-secondary);line-height:1.7}.selection-preview{padding:14px 16px;background:var(--el-fill-color-light);border-radius:8px;margin-top:16px;font-size:13px}.form-error{font-size:13px;color:var(--el-color-danger)}.el-alert{margin:14px 0}@media(max-width:800px){.editor-grid{grid-template-columns:1fr;gap:16px}.pick-list{height:230px}.list-tools{flex-wrap:wrap}.list-tools .el-select,.list-tools .el-input{max-width:none;width:100%}.filters{flex-wrap:wrap}.filters .el-select{width:100%}.panel{padding:14px}.compatibility-page :deep(.page-head){flex-wrap:wrap}}
</style>
